const P=window.People,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'—':Number(n).toLocaleString('ko-KR',{maximumFractionDigits:1});const won=n=>n==null?'—':fmt(Math.round(n/10000));const pct=(n,d)=>d?fmt(n/d*100)+'%':'—';
let state={tab:'overview',company:'전체',current:[],previous:[],demo:true,currentLoaded:true,previousLoaded:true,currentFile:'가상 예시자료 · 2026.09.30',previousFile:'가상 예시자료 · 2026.06.30',date:'2026-09-30',prevDate:'2026-06-30',error:'',suppress:false};
function sample(){const raw=[];for(let i=1;i<=124;i++){let company=i<=86?'플랜티넷':'플랜티엠',n=i<=86?i:i-86;const rank=['사원','사원','대리','대리','과장','차장','부장','임원'][i%8],join=i>112?`2026-0${7+i%3}-0${1+i%8}`:`${2011+i%15}-${String(1+i%12).padStart(2,'0')}-15`;raw.push({'회사':company,'사번':`${company==='플랜티넷'?'PN':'PM'}${String(n).padStart(3,'0')}`,'이름':`가상직원${i}`,'생년월일':`${1969+i%33}-${String(1+i%12).padStart(2,'0')}-10`,'성별':i%3===0?'여':'남','입사일':join,'퇴사일':i>120?'2026-08-15':'','부서':['경영지원','기술개발','사업운영','영업'][i%4],'직급':rank,'고용형태':i%12===0?'계약직':'정규직','연봉':({사원:3800,대리:4700,과장:5700,차장:6700,부장:7900,임원:11000}[rank]+i%7*120)*10000});}const rows=P.normalize(raw).rows;state.current=rows;state.previous=rows.filter(r=>r.join<='2026-06-30').map(r=>({...r,leave:null,salary:Math.round(r.salary/1.04)}));}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function data(){const cur=P.active(state.current,state.date,state.company),prev=P.active(state.previous,state.prevDate,state.company);return {cur,prev,s:P.summary(cur,state.date),p:P.summary(prev,state.prevDate)};}
const signed=n=>(n>0?'+':'')+fmt(n);function delta(a,b,unit='명'){if(!state.previousLoaded)return '<span class="delta">비교자료를 업로드해 주세요</span>';const d=a-b;return `<span class="chip ${d<0?'down':''}">${signed(d)}${unit}</span><span class="delta">이전 기준일 대비 ${b?pct(d,b):'비교 불가 (이전 0)'}</span>`;}
function head(title,sub,tag=''){return `<div class="panelhead"><div><h2>${title}</h2><p>${sub}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;}
function masked(n){return state.suppress&&n>0&&n<5?'5명 미만':fmt(n)+'명';}
function bars(items,total){if(!total)return '<div class="empty">집계할 재직자가 없습니다.</div>';const max=Math.max(...items.map(x=>x.count),1);return `<div class="horizontal">${items.map(x=>`<div class="barrow"><span>${esc(x.label)}</span><div class="track"><div class="fill" style="width:${state.suppress&&x.count>0&&x.count<5?0:x.count/max*100}%"></div></div><span class="barvalue">${masked(x.count)} <small>${state.suppress&&x.count>0&&x.count<5?'':pct(x.count,total)}</small></span></div>`).join('')}</div>`;}
function kpis(d){return `<div class="kpis"><div class="card dark"><div class="klabel">전체 재직 인원 <span class="kicon">◫</span></div><div class="number">${fmt(d.s.count)}<small>명</small></div>${delta(d.s.count,d.p.count)}</div><div class="card"><div class="klabel">연봉 합계 <span class="kicon">₩</span></div><div class="number">${d.s.paid?fmt(d.s.total/100000000):'—'}<small>억 원</small></div><div class="delta">연봉 입력 ${d.s.paid} / ${d.s.count}명 · 계약연봉 합계</div></div><div class="card"><div class="klabel">평균 연봉 <span class="kicon">↗</span></div><div class="number">${won(d.s.average)}<small>만 원</small></div><div class="delta">중앙값 ${won(d.s.median)}만 원 · 입력자 기준</div></div><div class="card"><div class="klabel">평균 연령 <span class="kicon">◷</span></div><div class="number">${fmt(d.s.age)}<small>세</small></div><div class="delta">만 나이 · 생년월일 입력 ${d.s.ageN}명</div></div></div>`;}
function companyPanel(){const rows=P.companies.map(c=>{const a=P.active(state.current,state.date,c),b=P.active(state.previous,state.prevDate,c),s=P.summary(a,state.date);return `<tr><td class="companyname"><span class="dot ${c==='플랜티엠'?'second':''}"></span>${c}</td><td>${masked(a.length)}</td><td>${state.previousLoaded?masked(b.length):'—'}</td><td class="change">${state.previousLoaded?signed(a.length-b.length):'—'}</td><td>${state.suppress&&a.length>0&&a.length<5?'—':won(s.average)}</td></tr>`;}).join('');return `<section class="panel">${head('회사별 인원 현황','두 회사의 재직 인원과 이전 기준일 대비 변화','그룹 전체')}<div class="tablewrap"><table><thead><tr><th>회사</th><th>현재 인원</th><th>이전 인원</th><th>증감 (명)</th><th>평균 연봉 (만원)</th></tr></thead><tbody>${rows}</tbody></table></div><p class="mini">회사별 표는 상단 회사 선택과 관계없이 그룹 전체를 비교합니다.</p></section>`;}
function tenurePanel(d){return `<section class="panel">${head('근속구간별 인원현황','입사일과 보고 기준일 사이의 근속 기간','5개 구간')}${bars(P.distribution(d.cur,state.date,'tenure'),d.cur.length)}</section>`;}
function agePanel(d){return `<section class="panel">${head('연령별 인원현황','보고 기준일의 만 나이 기준')}${bars(P.distribution(d.cur,state.date,'age'),d.cur.length)}</section>`;}
function genderPanel(d){const groups=['남성','여성','미입력/기타'].map(label=>({label,count:d.cur.filter(r=>r.gender===label).length})),colors=['#087e7d','#a1b9c8','#e5eaed'];let a=0;const stops=groups.map((x,i)=>{const b=a;a+=d.cur.length?x.count/d.cur.length*100:0;return `${colors[i]} ${b}% ${a}%`;}).join(',');return `<section class="panel">${head('성별 인원현황','미입력·기타 성별을 포함한 전체 재직자 기준')}<div class="gender">${state.suppress?'<div class="mini">소규모 집단 보호 적용</div>':`<div class="donut" style="background:${d.cur.length?'conic-gradient('+stops+')':'#edf2f3'}"><div class="donutcenter">${fmt(d.cur.length)}<small>TOTAL PEOPLE</small></div></div>`}<div class="genderstats">${groups.map((g,i)=>`<div><span><span class="dot" style="background:${colors[i]}"></span>${g.label}</span><span><b>${masked(g.count)}</b> <small>${state.suppress&&g.count>0&&g.count<5?'':pct(g.count,d.cur.length)}</small></span></div>`).join('')}</div></div></section>`;}
function rankTable(d){const ranks=P.ranks(d.cur,state.date);return `<div class="tablewrap"><table><thead><tr><th>직급</th><th>인원</th><th>연봉 입력</th><th>평균 연봉 (만원)</th><th>중앙값 (만원)</th><th>연봉 합계 (만원)</th><th>연봉 비중</th></tr></thead><tbody>${ranks.length?ranks.map(r=>{const hide=state.suppress&&r.count<5;return `<tr><td class="companyname">${esc(r.rank)}</td><td>${masked(r.count)}</td><td>${hide?'—':r.paid+'명'}</td><td>${hide?'—':won(r.average)}</td><td>${hide?'—':won(r.median)}</td><td>${hide||!r.paid?'—':won(r.total)}</td><td>${hide||!r.paid?'—':pct(r.total,d.s.total)}</td></tr>`;}).join(''):'<tr><td colspan="7" class="empty">집계할 자료가 없습니다.</td></tr>'}</tbody></table></div>`;}
function insights(d){if(!d.cur.length)return '';const t=P.distribution(d.cur,state.date,'tenure'),early=t[0].count+t[1].count;return `<div class="insights"><h3>REPORT HIGHLIGHTS</h3><p>${esc(state.company==='전체'?'그룹':state.company)} 재직자는 <b>${fmt(d.s.count)}명</b>입니다.${state.previousLoaded?` 이전 기준일 대비 <b>${signed(d.s.count-d.p.count)}명</b> 변동했습니다.`:''} 근속 3년 미만 인원이 ${state.suppress&&early<5?'5명 미만':`<b>${fmt(early)}명 (${pct(early,d.cur.length)})</b>`}이며, 연봉 입력률은 <b>${pct(d.s.paid,d.s.count)}</b>입니다. ${d.s.paid<d.s.count?'연봉 미입력자는 임금통계에서 제외했습니다.':''}</p></div>`;}
function structure(d){const deps=[...new Set(d.cur.map(r=>r.department))].map(label=>({label,count:d.cur.filter(r=>r.department===label).length})).sort((a,b)=>b.count-a.count);const types=[...new Set(d.cur.map(r=>r.type))].map(label=>({label,count:d.cur.filter(r=>r.type===label).length}));return `${kpis(d)}<div class="grid">${tenurePanel(d)}${agePanel(d)}${genderPanel(d)}<section class="panel">${head('고용형태별 인원','입력된 고용형태 기준')}${bars(types,d.cur.length)}</section><section class="panel wide">${head('부서별 인원','부서명별 재직 인원')}${bars(deps,d.cur.length)}</section></div>`;}
function pay(d){return `${kpis(d)}<section class="panel">${head('직급별 임금현황','재직자의 계약연봉 기준 · 실제 지급액 및 회사 부담금과 다릅니다.','단위: 만원')}${rankTable(d)}<p class="reportnote">평균·중앙값·합계는 연봉 입력자만 집계합니다. 연봉 0원은 입력값으로 포함합니다. 회사별 동일한 직급명을 사용하면 그룹 합산 시 같은 직급으로 묶입니다.</p></section>`;}
function dataView(){return `<div class="uploadgrid">${['current','previous'].map((k,i)=>`<section class="panel">${head(i?'02. 이전 기준일 자료':'01. 보고 기준일 자료',i?'증감을 비교할 당시의 인사자료':'보고할 시점의 인사자료')}<div class="drop"><span style="font-size:28px;color:#087e7d">⇧</span><b>엑셀 또는 CSV 파일 선택</b><div class="mini">.xlsx / .xls / .csv · 여러 파일 선택 가능<br>두 회사 파일을 함께 선택하거나 한 파일로 통합하세요.</div><input type="file" id="${k}Upload" accept=".xlsx,.xls,.csv" multiple aria-label="${i?'이전':'현재'} 인사자료 업로드"></div><div class="filelabel">${esc(state[k+'File']||'등록된 자료 없음')}<br>${state[k+'Loaded']?state[k].length+'개 원본 행 · '+P.active(state[k],i?state.prevDate:state.date).length+'명 재직':'미등록'}</div></section>`).join('')}<section class="panel wide">${head('입력 양식 및 데이터 검증','첫 행에 아래 항목명을 사용하세요. 시트명으로도 회사를 구분할 수 있습니다.')}<div class="actions"><button id="template" class="button primary">↓ 엑셀 입력양식</button><button id="sampleDownload" class="button">↓ 예시자료 엑셀</button><button id="loadDemo" class="button">예시 화면 다시 보기</button><button id="resetData" class="button">전체 자료 비우기</button></div><div class="tablewrap"><table><thead><tr><th>필수 입력</th><th>선택 입력</th><th>입력 기준</th></tr></thead><tbody><tr><td>회사 · 사번 · 입사일</td><td>이름 · 생년월일 · 성별 · 퇴사일<br>부서 · 직급 · 고용형태 · 연봉</td><td>날짜 YYYY-MM-DD<br>연봉: 원 단위 숫자 (예: 50000000)</td></tr></tbody></table></div><p class="method">회사명은 <b>플랜티넷 / 플랜티엠</b>으로 입력하세요. 사번은 회사 안에서 중복 없이 입력합니다. 엑셀의 ‘플랜티넷’, ‘플랜티엠’ 시트에 나눠 입력할 경우 회사 열이 비어 있어도 시트명으로 구분합니다. 양식의 ‘작성안내’ 시트는 분석에서 제외됩니다.<br>자료를 다시 올리면 해당 기준일의 기존 자료를 교체합니다. 퇴사일은 재직하지 않는 첫날로 처리하며, 기준일보다 늦게 입사한 사람은 제외합니다. 연봉이 비어 있으면 0원으로 바꾸지 않고 임금통계에서 제외합니다. 오류가 있으면 전체 업로드를 취소하고 기존 자료를 유지합니다.</p>${state.error?`<div role="alert" class="error">${esc(state.error)}</div>`:''}</section><section class="panel wide">${head('집계 기준과 개인정보 보호','자료 처리 방식과 보고 시 유의할 내용')}<div class="method">• 기준일 인원 = 입사일 ≤ 기준일, 퇴사일이 없거나 퇴사일 > 기준일인 사람입니다.<br>• 인원 증감 = 이번 기준일 재직 인원 − 이전 기준일 자료의 재직 인원입니다. 자료에 없는 퇴사자는 추정하지 않습니다.<br>• 근속구간은 정확한 입사일 기념일 기준으로 구분합니다. 연령은 만 나이로 계산합니다.<br>• 연봉 합계는 계약연봉의 합입니다. 급여 실지급액·퇴직급여·보험료를 포함한 총 인건비는 별도 자료가 필요합니다.<br>• 파일은 이 페이지의 브라우저 메모리에서만 처리합니다. 새로고침 또는 페이지 종료 시 인사자료가 사라집니다. 다운로드한 보고서는 사용자 기기에 저장됩니다.<br>• 실명·사번은 보고서에 표시하지 않습니다. 요약 보고서 엑셀에는 개인별 원본자료를 포함하지 않습니다.<br>• 이전 기준일 자료의 직급·연봉은 당시 값으로 입력하세요. 현 자료만으로 과거 연봉을 복원하지 않습니다.</div><p><label class="mini"><input id="suppress" type="checkbox" ${state.suppress?'checked':''}> 5명 미만 집단 보호: 일부 상세 차트·직급 통계를 숨김 (전체 합계 및 증감은 유지되므로 완전한 비식별화를 보장하지 않음)</label></p></section></div>`;}
function render(){const labels={overview:['그룹 인원현황','OVERVIEW'],structure:['인력 구성 분석','WORKFORCE'],pay:['직급별 임금현황','COMPENSATION'],data:['자료 업로드','DATA CENTER']};$('#pageTitle').textContent=labels[state.tab][0];$('#sectionLabel').textContent=labels[state.tab][1];document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));document.querySelectorAll('[data-company]').forEach(b=>b.classList.toggle('selected',b.dataset.company===state.company));$('#notice').innerHTML=`<span>${state.demo?'DEMO':state.currentLoaded?'DATA':'READY'}</span>${state.demo?'가상 예시자료로 구성된 화면입니다. 실제 보고에는 인사자료를 업로드해 주세요.':state.currentLoaded?'업로드한 인사자료로 집계했습니다. 브라우저 종료 시 자료는 사라집니다.':'인사자료를 업로드하면 회사별 보고 내용을 자동 생성합니다.'}<button id="clear">자료 비우기</button>`;$('#clear').onclick=reset;$('#subtitle').textContent=state.tab==='data'?'인사자료를 보고 가능한 숫자로 바꿉니다.':`${state.company} · 보고 ${state.date} / 비교 ${state.previousLoaded?state.prevDate:'자료 미등록'}`;const d=data();$('#view').innerHTML=state.tab==='overview'?`${kpis(d)}${insights(d)}<div class="grid">${companyPanel()}${tenurePanel(d)}${agePanel(d)}${genderPanel(d)}</div><section class="panel">${head('직급별 임금현황','연봉 입력자 기준 · 평균 / 중앙값 / 연봉 비중','단위: 만원')}${rankTable(d)}</section>`:state.tab==='structure'?structure(d):state.tab==='pay'?pay(d):dataView();if(state.tab==='data')bindData();}
function reset(){state.current=[];state.previous=[];state.currentLoaded=false;state.previousLoaded=false;state.demo=false;state.currentFile='';state.previousFile='';state.error='';render();toast('브라우저의 인사자료를 비웠습니다.');}
function downloadBook(sheets,name){const wb=XLSX.utils.book_new();sheets.forEach(([name,rows])=>{const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=(rows[0]||[]).map((_,i)=>({wch:i===0?22:19}));XLSX.utils.book_append_sheet(wb,ws,name);});XLSX.writeFile(wb,name);}
function template(){downloadBook([['작성안내',[['플랜티넷 그룹 인사자료 작성안내'],['필수항목','회사 / 사번 / 입사일'],['회사명','플랜티넷 또는 플랜티엠 (해당 시트에서는 빈칸 가능)'],['날짜','YYYY-MM-DD 또는 엑셀 날짜'],['연봉','원 단위 숫자. 비어 있으면 임금통계 제외'],['퇴사일','재직하지 않는 첫날. 재직자는 빈칸'],['사번','동일 회사 내 유일한 값. 앞자리 0은 텍스트로 입력'],['비교자료','이전 기준일 당시의 자료를 별도 파일로 작성'],['개인정보','이름은 선택항목. 서버 전송 없이 브라우저 내 집계']]],...P.companies.map(c=>[c,[P.headers]])],'그룹_인사자료_입력양식.xlsx');}
function report(){if(!state.currentLoaded)return toast('보고 기준일 자료를 먼저 업로드해 주세요.');const d=data();const companyRows=P.companies.map(c=>{const a=P.summary(P.active(state.current,state.date,c),state.date),b=P.summary(P.active(state.previous,state.prevDate,c),state.prevDate);return [c,a.count,state.previousLoaded?b.count:null,state.previousLoaded?a.count-b.count:null,a.paid,a.average,a.total];});const datasets=[['보고요약',[['보고 구분',state.demo?'가상 예시자료':'사용자 업로드 자료'],['회사 범위',state.company],['보고 기준일',state.date],['비교 기준일',state.previousLoaded?state.prevDate:'미등록'],['재직 인원',d.s.count],['이전 인원',state.previousLoaded?d.p.count:null],['증감',state.previousLoaded?d.s.count-d.p.count:null],['연봉 입력 인원',d.s.paid],['평균 연봉 (원)',d.s.average],['연봉 합계 (원)',d.s.paid?d.s.total:null],['평균 만 나이',d.s.age]]],['회사별',[['회사','현재 인원','이전 인원','증감','연봉 입력 인원','평균 연봉(원)','연봉 합계(원)'],...companyRows.map(r=>state.suppress&&r[1]>0&&r[1]<5?[r[0],'5명 미만',r[2],r[3],null,null,null]:r)]],...['tenure','age'].map((k,i)=>[i?'연령별':'근속별',[['구간','인원','구성비'],...P.distribution(d.cur,state.date,k).map(x=>[x.label,state.suppress&&x.count>0&&x.count<5?'5명 미만':x.count,state.suppress&&x.count>0&&x.count<5?null:d.cur.length?x.count/d.cur.length:null])]]),['성별',[['성별','인원'],...['남성','여성','미입력/기타'].map(g=>{const n=d.cur.filter(r=>r.gender===g).length;return [g,state.suppress&&n>0&&n<5?'5명 미만':n];})]],['직급별임금',[['직급','인원','연봉 입력 인원','평균 연봉(원)','중앙값(원)','연봉 합계(원)','연봉 비중'],...P.ranks(d.cur,state.date).map(r=>state.suppress&&r.count<5?[r.rank,'5명 미만',null,null,null,null,null]:[r.rank,r.count,r.paid,r.average,r.median,r.paid?r.total:null,d.s.total?r.total/d.s.total:null])]],['집계기준',[['항목','기준'],['재직','입사일 ≤ 기준일, 퇴사일 없음 또는 퇴사일 > 기준일'],['연령 / 근속','기념일 기준 만 연수'],['임금','입력된 계약연봉(원), 공란 제외, 0원 포함'],['증감','별도 업로드한 두 기준일 자료의 재직인원 차이'],['유의사항','계약연봉 합계는 총 인건비 또는 지급급여가 아님'],['소규모 보호',state.suppress?'사용 (전체 합계와 증감 유지)':'미사용']]]];downloadBook(datasets,`인원현황_보고_${state.date}.xlsx`);}
async function upload(files,key){if(!files.length)return;try{if(files.length>10)throw Error('한 번에 10개 이하의 파일을 선택하세요.');let records=[];for(const f of files){if(f.size>15*1024*1024)throw Error('파일은 개당 15MB 이하로 선택하세요.');const wb=XLSX.read(await f.arrayBuffer(),{type:'array',cellDates:true});let found=false;for(const name of wb.SheetNames){if(/안내|설명|readme/i.test(name))continue;const ws=wb.Sheets[name],raw=XLSX.utils.sheet_to_json(ws,{defval:''});if(!raw.length)continue;if(!Object.keys(raw[0]).some(k=>String(k).replace(/\s/g,'')==='사번'))continue;found=true;raw.forEach((r,i)=>{if(P.companies.includes(name)&&!r['회사']&&!r['회사명'])r['회사']=name;r.__source=`${f.name} / ${name} / ${i+2}행`;records.push(r);});}if(!found)throw Error(`${f.name}: 첫 행에 사번·입사일 등 항목명이 있는 시트가 필요합니다.`);}if(records.length>50000)throw Error('최대 50,000행까지 분석할 수 있습니다.');const result=P.normalize(records);if(result.errors.length)throw Error(result.errors.slice(0,25).join('\n')+(result.errors.length>25?`\n외 ${result.errors.length-25}개 오류`:''));if(state.demo){state.current=[];state.previous=[];state.currentLoaded=false;state.previousLoaded=false;state.currentFile='';state.previousFile='';state.demo=false;}state[key]=result.rows;state[key+'Loaded']=true;state[key+'File']=Array.from(files).map(f=>f.name).join(' · ');state.error='';render();toast(`${key==='current'?'보고':'비교'} 자료 ${result.rows.length}행을 읽었습니다.`);}catch(e){state.error=e.message;render();toast('업로드를 취소했습니다. 오류 내용을 확인해 주세요.');}}
function bindData(){$('#currentUpload').onchange=e=>upload(Array.from(e.target.files),'current');$('#previousUpload').onchange=e=>upload(Array.from(e.target.files),'previous');$('#template').onclick=template;$('#sampleDownload').onclick=()=>{const saved=state;state={...state};sample();const rows=state.current;state=saved;downloadBook([['인사자료',[P.headers,...rows.map(x=>[x.company,x.id,x.name,x.birth,x.gender,x.join,x.leave||'',x.department,x.rank,x.type,x.salary])]]],'가상_인사자료_예시.xlsx');};$('#loadDemo').onclick=()=>{state.demo=true;state.currentLoaded=true;state.previousLoaded=true;state.currentFile='가상 예시자료 · 2026.09.30';state.previousFile='가상 예시자료 · 2026.06.30';state.date='2026-09-30';state.prevDate='2026-06-30';$('#currentDate').value=state.date;$('#previousDate').value=state.prevDate;state.error='';sample();render();};$('#resetData').onclick=reset;$('#suppress').onchange=e=>{state.suppress=e.target.checked;render();};}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});document.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>{state.company=b.dataset.company;render();});$('#uploadNav').onclick=()=>{state.tab='data';render();};$('#applyDates').onclick=()=>{const a=$('#currentDate').value,b=$('#previousDate').value;if(!a||!b||b>=a)return toast('비교 기준일은 보고 기준일보다 앞선 날짜로 입력하세요.');state.date=a;state.prevDate=b;render();toast('기준일을 적용했습니다. 각 시점의 인사자료인지 확인해 주세요.');};$('#print').onclick=()=>{if(state.tab==='data')state.tab='overview';render();window.print();};$('#reportExport').onclick=report;sample();render();
